require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/Sync.php';require_once __DIR__.'/../core/StaticGen.php';use Core\Sync;use Core\StaticGen;$args=array_slice(isset($argv)?$argv:array(),1);$quiet=false;$opts=array('task'=>'trending','force'=>false,'window'=>'week','limit'=>40,'build'=>1,);$argError='';$i=0;$nArgs=count($args);while($i<$nArgs){$a=(string)$args[$i];if($a==='--force'){$opts['force']=true;$i++;continue;}if($a==='--quiet'||$a==='-q'){$quiet=true;$i++;continue;}if($a==='--no-build'){$opts['build']=0;$i++;continue;}if($a==='--help'||$a==='-h'){echo"php cron/sync_trending.php [--limit N] [--window day|week] [--order hot|popular|both]\n";exit(0);}if(strpos($a,'--')!==0){$argError='无法识别的参数：'.$a;break;}$eq=strpos($a,'=');if($eq!==false){$key=substr($a,2,$eq-2);$val=substr($a,$eq+1);$i++;}else{$key=substr($a,2);if(!in_array($key,array('limit','window','order'),true)){$argError='未知参数：'.$a;break;}if($i+1>=$nArgs||strpos((string)$args[$i+1],'--')===0){$argError='参数缺少值：'.$a;break;}$val=$args[$i+1];$i+=2;}if($key==='limit'){$opts['limit']=(int)$val;}elseif($key==='window'){$opts['window']=(string)$val;}elseif($key==='order'){$opts['order']=(string)$val;}else{$argError='未知参数：--'.$key;break;}}if($argError!==''){fwrite(STDERR,$argError."\n");exit(1);}if($opts['limit']<1||$opts['limit']>200){fwrite(STDERR,"--limit 范围必须是 1~200。\n");exit(1);}if(!in_array($opts['window'],array('day','week'),true)){fwrite(STDERR,"--window 只能是 day 或 week。\n");exit(1);}if(isset($opts['order'])&&!in_array($opts['order'],array('hot','popular','both'),true)){fwrite(STDERR,"--order 只能是 hot、popular 或 both。\n");exit(1);}$r=Sync::run($opts);$built=0;if(!empty($opts['build'])){try{$built=StaticGen::buildAll();}catch(\Throwable $ex){fwrite(STDERR,'build static failed: '.$ex->getMessage()."\n");}}echo sprintf("Synced: fetched=%d inserted=%d skipped=%d requests=%d | static page